cd /home/ubuntu/koha-test
echo '' | base64 -d > entrypoint.sh; chmod 755 entrypoint.sh
docker update --restart=no koha-test >/dev/null; for i in $(seq 1 30); do [ "$(docker inspect -f '{{.State.Running}}' koha-test)" = false ] && break; sleep 2; done
docker cp -a entrypoint.sh koha-test:/setup/entrypoint.sh
docker update --restart=unless-stopped koha-test >/dev/null; docker start koha-test >/dev/null; sleep 55
docker ps --filter name=koha-test --format '{{.Status}}'
docker logs --tail 4 koha-test 2>&1 | cut -c1-200
curl -s -o /dev/null -w "staff %{http_code}\n" -m 30 https://koha.azoclinic.duckdns.org/cgi-bin/koha/mainpage.pl
curl -s -o /dev/null -w "opac %{http_code}\n" -m 30 https://opac.azoclinic.duckdns.org/
curl -s -m 30 -o /tmp/spec.json -w "spec %{http_code}\n" https://koha.azoclinic.duckdns.org/api/v1/; head -c 120 /tmp/spec.json; echo
